-- 057. Эксперты (Кан, Сеитова, Абишев, Бейсенов): главные реплики под озвучку (проверка voice-checker 25.11).
-- Без сокращений (ГАИ, ИЦ, АТС, РОВД, АОН, ФРГ, МВД), омографов, «судим», время словами. Только текст; audio_url сохраняется.
begin;
-- kan
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R01' then jsonb_set(r, '{text}', to_jsonb('"Кан снимает очки. Протирает полой халата. Долго.\n— Не угорел он, голубчик. Угоревший — он розовый. А этот синий, одутловатый, в глазах точечные кровоизлияния. Удушение, шею сдавили. В машину его посадили мёртвым. Смерть — суббота, около десяти вечера. Ну, час туда-сюда.\nДальше. На запястьях слабые следы: связывали поверх рукавов. Щетина дня два, обезвоживание, голодал. Двое суток он где-то был. И не по своей воле.\nИ вот ещё. Под ногтями кровь. У него первая группа. А под ногтями вторая. Чья — это не ко мне."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R29' then jsonb_set(r, '{text}', to_jsonb('"Кабинет. Двое понятых. Кан просит задержанного положить левую руку на стол и сам разматывает бинт. Виток за витком.\n— Ожога нет. Ни пузыря, ни пятна.\nБерёт лупу.\n— Царапины. Три, параллельные, края дугой. Это ногти, человеческие. От животного следы другие, я их видел достаточно. Давность — от четырёх до шести суток, заживают. Вечеру субботы не противоречит.\nТеперь второе. По медкарте колонии группа вторая. Под ногтями покойного тоже вторая. Только вторая — у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины отдельно, группа отдельно. Я описываю, что вижу. Складывать будете вы."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R49' then jsonb_set(r, '{text}', to_jsonb('"Кан надевает очки, читает с листа.\n— Таблица. Запросил медкарты и учётные дела на всех, кто у вас в деле с фамилией и адресом. Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела, он в милиции служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — это не отпечаток пальца. Исключить человека она может. Назвать — нет."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R52' then jsonb_set(r, '{text}', to_jsonb('"Валентина Петровна вспомнила: в воскресенье рука у него была расцарапана. «Собака на базаре».\nКан кивает. В кабинете, при понятых, разматывает бинт на кисти задержанного.\n— Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает: от собаки покусы, когти, след другой. Давность — от четырёх до шести суток, заживают. С вечером субботы совместимо. Группа у него по медкарте колонии вторая. Под ногтями покойного тоже вторая. Я описываю кисть. Выводы делайте сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R53' then jsonb_set(r, '{text}', to_jsonb('"Кан дописывает строку в свою таблицу.\n— Бекенова, задержанного, привели с утра. Кровь взял: вторая группа. Кисти посмотрел у него и, для порядка, у Ахметова. Тот пришёл сам, рукава засучил без разговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат у гаишников узнал: прав и машины у Бекенова нет. Водить, говорит, умеет. Вот. Я описываю. Складываете вы."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'a6c62ec0-5ff9-53a5-b9a2-20898741074b';
-- seitova
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R03' then jsonb_set(r, '{text}', to_jsonb('"Сеитова раскладывает кальку на капоте служебного «уазика».\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер. Протектор глубокий, на каблуке косой порез, около сантиметра. Следы под тонким снегом. Снег, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часу.\nВторой: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти. Оставлены раньше, засветло, пока грязь была мягкая.\nИ борозды. Две, параллельные, со стороны водительской двери. Тело несли, ноги волочились. Чьи следы — не скажу. Размер скажу."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R24' then jsonb_set(r, '{text}', to_jsonb('"Сеитова не поднимает головы от стола.\n— Три тысячи. Тридцать купюр по сто. Сверила с ксерокопиями: серия, номер. У двух купюр надрыв на краю, на копии он тоже виден. Каждая из тридцати есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — это не ко мне."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R27' then jsonb_set(r, '{text}', to_jsonb('"Сеитова снимает перчатки.\n— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам. Совпали по всем шести.\nМужские следы у гаража дачи оставлены этими ботинками. Кто был в ботинках — вопрос не ко мне."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R30' then jsonb_set(r, '{text}', to_jsonb('"Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\nСеитова раскладывает купюры рядом с листами ксерокопий.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». Сверила номера. Каждая из пяти есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесла в протокол. Больше по конверту ничего."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R47' then jsonb_set(r, '{text}', to_jsonb('"Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду. Плату оставляет сохнуть на батарее. Наутро ставит новую батарейку.\n— Включился. Последнее принятое сообщение в памяти: четверг, двадцать первое, тридцать пять минут шестого вечера. Позже ничего. В воде аппарат не принимает. Что на него слали после — это у оператора, к Абишеву. Арык у ворот сфотографировала. Где лежал — в протоколе."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R59' then jsonb_set(r, '{text}', to_jsonb('"Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nСеитова кладёт пять купюр рядом с листами ксерокопий. Ведёт линейкой по строчкам.\n— Каждая из пяти есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R60' then jsonb_set(r, '{text}', to_jsonb('"Сеитова кладёт рядом две кальки.\n— Дактокарта Бекенова. Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев через гаишников: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела всё в одну бумагу."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = 'd3ddcd6d-4093-5464-970c-de4ad3cb9af1';
-- abishev
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— Ну, судимости. Дактокарты. Адресное бюро, машины через гаишников. Могу написать запрос на телефонную станцию, в пейджинговую, в электросети. Всё письменно, с подписью, и всё через день. Компьютер у нас, вот, один. И тот в бухгалтерии."'::json #>> '{}')) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R02' then jsonb_set(r, '{text}', to_jsonb('"Абишев берёт пейджер двумя пальцами. С него капает.\n— Ну, этот своё отработал. А номер на крышке есть. Набрал пейджинговую, девочки там нормальные, журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали. Из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз. И от матери. В офисе говорят: так ни разу и не отозвался.\nА прочитал он или нет — этого никто не скажет. Пейджер в одну сторону работает: оператор отправил, и всё. Выводы делайте сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R10' then jsonb_set(r, '{text}', to_jsonb('"Абишев листает протокол РОВД.\n— Отключение света, значит. А было ли оно, райотдел проверять не стал. Ну ладно. Написал запрос диспетчеру районных электросетей по Кок-Тобе. После сам съездил: без печати бумагу не отдают. Вот. В субботу с семи вечера до двух ночи район Кок-Тобе обесточен. По графику.\nПро другие районы я не спрашивал: там на каждый район отдельная бумага. Так что света на даче не было. Тут райотдел прав."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R12' then jsonb_set(r, '{text}', to_jsonb('"Абишев переписывает цифры с АОН на сигаретную пачку.\n— Суббота, половина четвёртого. Хорошо, что у неё определитель на девяносто девять номеров. Был бы на двадцать — за два дня соболезнований этот номер давно бы вытеснило. По первым цифрам — частный сектор под горами. Ждите.\nЧерез час возвращается с листком.\n— Значит, так. Телефон зарегистрирован на Шмидта Г. Выбыл в Германию, на постоянное. Адрес — частный сектор в Горном Гиганте. Участковый тамошний говорит: дом пустой, продаётся по доверенности. А телефон не отключён. Выходит, звонок был из пустого дома. На кого доверенность — это к нотариусу. А там неделя, не меньше."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R13' then jsonb_set(r, '{text}', to_jsonb('"— Номер, который ваш финансист с определителя запомнил? — Абишев кивает. — Бухгалтеры, они цифры помнят. Пробил через адресное бюро. Шмидт Г., выбыл в Германию на постоянное жительство. Частный сектор в Горном Гиганте. Участковый говорит: дом пустой, продаётся по доверенности. На кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу был звонок."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R17' then jsonb_set(r, '{text}', to_jsonb('"Абишев трёт глаза. Ночь не спал.\n— Пальцы с люка и с лампы. Гульнара сняла чисто, на копоти хорошо отпечаталось. Сравнивал вручную, по картотеке, всю ночь. Начал с тех, кто у вас в деле есть и на кого есть дактокарта.\nЕсть совпадение. Мамаджанов Фархад. Осуждён в девяносто четвёртом, таможенное дело.\nВторой набор с люка в картотеке не значится. Человек несудимый, на таких карточек нет.\nИ вот ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Это я так, к сведению."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R20' then jsonb_set(r, '{text}', to_jsonb('"Абишев вертит в руках пейджер охранника.\n— Логику понял. Пустой дом знали, и четверги знали. Пустой дом — это бумаги, нотариус. А что хозяин по четвергам без шофёра ездит — это люди. Это знали на базе. Сообщения он стёр. Только у пейджинговой свой журнал: что им диктуют, то они и записывают.\nКладёт перед вами листок, переписанный от руки.\n— Четверг, двадцать первое. Половина пятого. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.» — оператор не спрашивает. В журнале этого нет."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R235' then jsonb_set(r, '{text}', to_jsonb('"— «Орбиту» я проверял. Свет там был и в пятницу, и в субботу. Справка у вас."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R236' then jsonb_set(r, '{text}', to_jsonb('"— «Орбиту» я проверял. Свет там был и в пятницу, и в субботу. Справка у вас."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R38' then jsonb_set(r, '{text}', to_jsonb('"— Мамаджанов? Он у нас есть. Осуждён в девяносто четвёртом, таможня, дактокарта с тех пор лежит. — Абишев тянет с полки ящик картотеки. — Сравнивал вручную, полночи. Пальцы с крышки люка и с керосиновой лампы — его, Гульнара подтвердит. Второй набор с люка в картотеке не значится: человек несудимый. И раз я всё равно в его деле сидел: медкарта колонии, группа крови вторая. Это так, к сведению. В медицине я не понимаю."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R48' then jsonb_set(r, '{text}', to_jsonb('"— Подождите. Соседка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил: сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» никто не проверял. Сейчас. Заодно и пятницу спрошу, чтобы два раза не звонить.\nЗвонит. Ждёт. Записывает.\n— Диспетчер говорит: в «Орбите» ни в пятницу, ни в субботу отключений не было. Свет был. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра. Знать вы это можете сегодня же."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R51' then jsonb_set(r, '{text}', to_jsonb('"Абишев тянется за сигаретами.\n— «Волга» с одной фарой? По вашему кругу запросил информационный центр и гаишников. Мамаджанов Ф. — «Волга», двадцать четвёртая, белая. Что у неё с фарами, гаишники не пишут, в карточке такого нет. Ахметов — «девятка», белая. Попросил гаишников глянуть у офиса: фары целы, обе. Жумабаева — «Таврия», красная. Нуртазин — личной машины нет, ездит на служебном «уазике» агентства. Белых, значит, две. Дальше смотрите сами."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R57' then jsonb_set(r, '{text}', to_jsonb('"Абишев рисует таблицу на обороте старой ориентировки.\n— Даты свёл, раз бумаги у меня. Чайхана, где охраннику долг списали, — девятое, суббота. «Волга» с одной фарой у ворот базы — четырнадцатое, четверг. «Месяц тебе, или сядешь» — шестнадцатое, суббота. Похищение — двадцать первое.\nТычет ручкой в первые две строки.\n— Вот эти две — раньше крика в кабинете. Больше тут ничего не написано. Остальное — ваше."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R58' then jsonb_set(r, '{text}', to_jsonb('"Абишев откладывает пейджер охранника.\n— Номер на наклейке есть. Набрал пейджинговую. Журнал за двадцать первое: половина пятого, абонент Нуртазин, текст «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто подписался «Ф.», в журнале не пишут. Это справка, не обвинение."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '14e9bc6d-22f0-5005-b51c-e0678d8fa225';
-- beisenov
update characters set intro_text = replace(intro_text, 'Предположения потом.', 'Предположения после.') where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set fixed_questions = jsonb_set(fixed_questions, '{0,a}', to_jsonb('"— Типологией. Я могу сказать, как обычно ведут себя люди в такой ситуации и кто в неё, как правило, попадает. А кто попал в вашу — это дело следствия. Не науки."'::json #>> '{}')) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R23' then jsonb_set(r, '{text}', to_jsonb('"Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал это место, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
update characters set reaction_rules = (select jsonb_agg(case when r->>'id' = 'R56' then jsonb_set(r, '{text}', to_jsonb('"Бейсенов раскладывает на столе четыре листка с показаниями. По датам, слева направо. Карандашом — по каждому.\n— Давайте по хронологии. Девятое ноября, суббота: разговор в чайхане. Наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста, «месяц тебе, или сядешь». Двадцать первое: похищение.\nПодготовка началась за неделю до того, как у финансиста появилась причина. А как правило, бывает наоборот: сначала мотив, после план. Имён я не называю. Это порядок дат."'::json #>> '{}')) else r end) from jsonb_array_elements(reaction_rules) r) where id = '11b90ca2-3c48-573f-95ac-041cf0635f90';
commit;
